var sda=null,cfg=null,filesize=0,showAddr=!0,showCode=!0,upperCase=!1,result=[];function isHex(a){for(var b,c=a.toUpperCase(),d=0;d<c.length;d++)if(b=c.charCodeAt(d),!(48<=b&&57>=b||65<=b&&70>=b))return!1;return!0}function getSelectValue(a){for(var b=document.getElementById(a),c=0;c<b.length;c++)if(b[c].selected)return b[c].value;return!1}function loadFile(a,b){var c=new FileReader;c.onload=b,c.readAsBinaryString(a)}function result2text(){var a,b,c="";for(a=0;a<result.length;a++){var d=result[a][0],e=result[a][1],f=result[a][2],g=result[a][3];if(showAddr&&(c+=sprintf(upperCase?"$%06X ":"$%06x ",d)),showCode){for(b=0;b<f;b++)c+=sprintf(upperCase?"%04X ":"%04x ",e[b]);for(b=f;5>b;b++)c+="     "}if(c+=upperCase?g.toUpperCase():g,c+="\n",d+2*f>=filesize)break}return c}function init(){try{sda=new ScriptedDisAssembler,cfg=sda.getConfig()}catch(a){throw a}}function disass(){try{result=sda.disassemble(),document.getElementById("disass_code").value=result2text(),document.getElementById("disass_cfg").style.display="table",document.getElementById("disass_code").style.display="inline"}catch(a){throw a}}function updFile(){var a=document.getElementById("cfg_file").files[0];a&&loadFile(a,function(b){cfg.code=b.target.result,cfg.offset=0,filesize=b.target.result.length;var c=document.getElementById("cfg_filename");c.className="",c.innerHTML=a.name,document.getElementById("cfg_offset").value="0",disass()})}function updOffset(){var a=document.getElementById("cfg_offset");if(isHex(a.value)){var b=parseInt(a.value,16);b<filesize?(cfg.offset=b,disass()):(alert(sprintf("The value at 'Offset' is behing the file-size. (max $%x)",filesize-1)),a.focus())}else alert("The value at 'Offset' in not a hexadecimal number."),a.focus()}function updLimit(){var a=document.getElementById("cfg_limit");cfg.limit=parseInt(a.value),disass()}function updNext(){var a=result[result.length-1][0],b=result[result.length-1][2];cfg.offset=a+2*b,document.getElementById("cfg_offset").value=sprintf("%x",cfg.offset),disass()}function updRadix(){cfg.radix=parseInt(getSelectValue("cfg_radix")),disass()}function updPrefx(){cfg.prefx=1==parseInt(getSelectValue("cfg_prefx"))?"$":"0x",disass()}function updWidth(){cfg.width=parseInt(getSelectValue("cfg_width")),disass()}function updCase(){upperCase=document.getElementById("cfg_case").checked,disass()}function updReloc(){cfg.reloc=document.getElementById("cfg_reloc").checked,disass()}function updShowAddr(){showAddr=document.getElementById("cfg_showAddr").checked,disass()}function updShowCode(){showCode=document.getElementById("cfg_showCode").checked,disass()}